    def add_delete(self):
        row = self.tableWidget.currentRow()
        col = self.tableWidget.currentColumn()
        # print(row,col)
        if self.factor_list:
            if col==5:
                self.factor_list[row]['No'] +=1
                self.factor_list[row]['Total'] = (self.factor_list[row]['No']*self.factor_list[row]['Price'])
            if col==6:
                if self.factor_list[row]['No']>=2:
                    self.factor_list[row]['No'] -=1
                    self.factor_list[row]['Total'] = (self.factor_list[row]['No']*self.factor_list[row]['Price'])
                else:
                    self.factor_list.pop(row)
        self.summ()

        if self.lineEdit.text() == '0':
            self.pushButton_2.setEnabled(False)
            self.actionSave_Factor.setEnabled(False)
        else:
            # if self.customer_id != None:
            if self.label.text():
                self.pushButton_2.setEnabled(True)
                self.actionSave_Factor.setEnabled(True)
            else:
                self.pushButton_2.setEnabled(False)
                self.actionSave_Factor.setEnabled(False)

        
        self.show_table()
                

    def active_btn_add(self):
        if self.comboBox_2.currentIndex()!=0 and self.spinBox.value()!=0:
            self.pushButton.setEnabled(True)
        else:
            self.pushButton.setEnabled(False)

    def add_to_list(self):
        # if self.comboBox_2.currentIndex()==0 or self.spinBox.value()==0:
        #     return
        new_dict = {'Id':self.products[self.comboBox_2.currentIndex()]['id'],
                    'Name':self.comboBox_2.currentText(),
                    'Price':self.products[self.comboBox_2.currentIndex()]['Price'],
                    'No':self.spinBox.value(),
                    'Total':(self.products[self.comboBox_2.currentIndex()]['Price'])*(self.spinBox.value())}
        for i in self.factor_list:
            if i['Id'] == new_dict['Id']:
                i['No'] += new_dict['No']
                i['Total'] += new_dict['Total']
                break
        else:
            self.factor_list.append(new_dict)
        self.summ()

        if self.label.text():
            self.pushButton_2.setEnabled(True)
            self.actionSave_Factor.setEnabled(True)

        self.show_table()

        # self.lineEdit.setText(str(sum([self.factor_list[row]['Total'] for row in range(len(self.factor_list))])))

        
        
    def fill_combobox(self):
        self.products = [{'id':-1, 'Name':'Select one...', 'Price':0}]
        result = self.mydb.read_products()
        for i in result:
            self.products.append({'id':i['id'],'Name':i['name'],'Price':i['price']})
        # for i in range(len(result)):
        #     self.products.append({'id':result[i][0],'Name':result[i][1],'Price':result[i][2]})
        # print(self.products)
        self.comboBox_2.clear()
        for i in self.products:
            self.comboBox_2.addItem(i['Name'])

    def show_table(self):
        column_name = ['Id','Name','No','Price','Total','Add','Delete']
        cols = len(column_name)
        rows = len(self.factor_list)
        self.tableWidget.setColumnCount(cols)
        self.tableWidget.setRowCount(rows)

        for row in range(rows):
            item = QTableWidgetItem(str(row+1))
            self.tableWidget.setVerticalHeaderItem(row,item)

        for index , col_name in enumerate(column_name):
            item = QTableWidgetItem(col_name)
            self.tableWidget.setHorizontalHeaderItem(index,item)

        for row in range(rows):
            for col in range(cols-2):
                item = QTableWidgetItem(str(self.factor_list[row][column_name[col]]))
                # item.setFlags(QtCore.Qt.NoItemFlags)
                self.tableWidget.setItem(row,col,item)

        # icon = QtGui.QIcon()
        # icon.addPixmap(QtGui.QPixmap("pic/1.png"),QtGui.QIcon.Normal,QtGui.QIcon.Off)
        for row in range(rows):
            for col in range(5,7):
                # item = QTableWidgetItem("+" if col==5 else "-")
                # item.setTextAlignment(QtCore.Qt.AlignCenter)
                # # item.setIcon(icon)
                # self.tableWidget.setItem(row,col,item)

                self.btn_add_del= QPushButton("+" if col==5 else "-")
                self.tableWidget.setCellWidget(row,col,self.btn_add_del)
                self.btn_add_del.clicked.connect(self.add_delete)

        self.comboBox_2.setCurrentIndex(0)
        self.spinBox.setValue(0)


